C:  Bridge

  ·ͣɺ֤ ลʹ͍ͭͯ ڮ Ͱ͋Δ͔Λ൑ఆ͢Δ͜ͱΛ ߟ ͑·͢ɻάϥϑ͔ΒลΛऔΓআ͍ͨͱ͖ʹɺඇ࿈ ݁ άϥϑ

 ͱͳΔลΛ ڮ ͱ ݺ ͿͷͰɺ͜ͷఆ ٛ ʹͦͬͯௐ΂͍͖ͯ·͢ɻ͕ͨͬͯ͠ɺ֤ ลΛάϥϑ͔ΒऔΓআ͍ͯɺάϥ
 ϑ͕࿈݁Ͱ͋Δ͔Λ൑ఆ͠·͢ɻάϥϑͷ࿈݁൑ఆʹ͸ɺਂ͞༏ઌ୳ࡧ (DFS)ɺ෯༏ઌ୳ࡧ (BFS)ɺUnion ﬁndɺ
 ϫʔγϟϧϑϩΠυ๏ͳͲ͕ ࢖ ͑·͢ɻࠓ ճͷ໰୊ͷ੍໿Ͱ͋Ε͹ɺ͜͜Ͱ ڍ ͛ͨΞϧΰϦζϜͷͲΕΛ ࢖ͬͯ

 ΋ɺे෼ʹ ؒ ʹ߹͍·͢ɻ
  ͜͜Ͱ͸ɺάϥϑͷ࿈݁൑ఆͷͨΊͷ DFS ͷ࣮૷ʹ͍ͭͯઆ໌͠·͢ɻάϥϑͷ࿈݁൑ఆͷͨΊͷ DFS ͸ɺҎ
 Լͷ ٙࣅίʔυͰදΘ͞ΕΔ ࠶ؼؔ਺Ͱ࣮૷͢Δ͜ͱ͕Ͱ͖·͢ɻ

     1: procedure DFS( ݱࡏ ͷ௖఺v)
     2:  ௖఺v Λ๚໰ࡁΈʹ͢Δ
     3:    for ௖఺v2: ௖఺v ʹྡ઀͍ͯ͠Δ͔ͭະ๚໰do

     4:      DFS(v2)

     5:   end for

     6:    return

     7: end procedure


  ࿈݁൑ఆΛ͢Δࡍʹ͸ɺશͯͷ௖఺Λະ๚໰ʹ͔ͯ͠Βɺ೚ҙͷ 1 ͭͷ௖఺͔Β DFS Λݺͼ·͢ɻͦͷޙʹશ
 ͯͷ௖఺͕๚໰ࡁΈͳΒ͹࿈݁Ͱ͋Γɺͦ͏Ͱͳ͍৔߹͸ඇ࿈݁Ͱ͢ɻ·ͨɺάϥϑͷลͷܨ͕Γ͸ྡ઀ߦྻͰ؅
 ཧͰ͖ɺྡ઀ ߦྻ͸ 2 ࣍ݩ഑ྻͰ࣮૷͢Δ͜ͱ͕Ͱ͖·͢ɻ
  Ҏ্Λ·ͱΊΔͱɺ֤ ลΛάϥϑ͔ΒऔΓআ͍ͯɺάϥϑ͕࿈ ݁ Ͱ͋Δ͔Λ൑ఆͯ͠ɺඇ࿈ ݁ ͱͳΔ৔ ߹ Λ਺
 ্͑͛·͢ɻDFS Λ༻͍ͨ৔ ߹ ͷ ࣌ؒܭࢉ ྔ͸ɺάϥϑͷ࿈ ݁ ൑ఆʹ O(N + M) Ͱ͔͔ΔͨΊɺશମͷ ࣌ؒܭ
 ࢉྔ͸ O(M(N + M)) ͱͳΓؒʹ߹͍·͢ɻ


  C++ͷίʔυྫ(ྡ઀ ߦྻͰάϥϑΛ؅ཧͯ͠ɺDFS Ͱ࿈݁൑ఆ͢Δ)



 1 const int limit = 50;


 2

 3 int n, m;
 4 int a[limit], b[limit];


 5

 6 bool graph[limit][limit];

 7 bool visited[limit];


 8

 9 void dfs(int v) {

10     visited[v] = true;
11     for (int v2 = 0; v2 < n; ++v2) {

12         if (graph[v][v2] == false) continue;
13         if (visited[v2] == true) continue;

14         dfs(v2);
15     }

16 }


17

18 int main(void) {


                                                  3

19     cin >> n >> m;


20

21     for (int i = 0; i < m; ++i) {

22         cin >> a[i] >> b[i];

23         a[i]--, b[i]--;

24         graph[a[i]][b[i]] = graph[b[i]][a[i]] = true;

25     }


26

27     int ans = 0;


28

29     for (int i = 0; i < m; ++i) {

30         graph[a[i]][b[i]] = graph[b[i]][a[i]] = false;


31

32         for (int j = 0; j < n; ++j) visited[j] = false;


33

34         dfs(0);


35

36         bool bridge = false;

37         for (int j = 0; j < n; ++j) if (visited[j] == false) bridge = true;

38         if (bridge) ans += 1;


39

40         graph[a[i]][b[i]] = graph[b[i]][a[i]] = true;

41     }


42

43     cout << ans << endl;


44

45     return 0;

46 }





